#!/usr/bin/env python3
from ast import literal_eval

messages = [
    '[208, 255, 271, 108, 236, 171, 68, 219, 13]',
    '[177, 270, 173, 94, 79, 120, 65, 126, 30]',
    '[64, 159, 151, 108, 236, 171]',
    '[182, 233, 160, 35, 120, 2]',
    '[106, 226, 197, 106, 115, 124, 8, 39, -7]'
]

def blockify(msg, size=3):
    lst = literal_eval(msg)
    blocks = [lst[i:i+size] for i in range(0, len(lst), size)]
    padding = False
    note = ""
    # If final block not full size or contains a weird number (e.g., negative, high value)
    if len(blocks[-1]) < size:
        padding = True
        note += 'last block is short; likely padded. '
    if any(x < 0 or x > 255 for x in blocks[-1]):
        padding = True
        note += 'last block is suspicious (negative or >255); check for padding from -1. '
    return blocks, padding, note

common_words = ['matrix', 'password', 'flag', 'test', 'pass', 'hello', 'hi']

def analyze_blocks():
    for idx, m in enumerate(messages):
        blocks, padded, note = blockify(m)
        print(f"Message {idx+1}: {blocks}")
        if padded:
            print(f"  [!] Padding detected: {note}")
        else:
            print("  No obvious padding.")
        # Check for drop in length (potentially short word) or suspicious block sizes
        if len(blocks) == 2:
            print("  [Info] Only two blocks, possibly short word/phrase.")
        # Comment if any block is obviously suspicious or plaintext-like
        for b in blocks:
            if any(x < 0 for x in b):
                print(f"  [Info] Block with negative entry: {b}")
        print()

if __name__ == "__main__":
    analyze_blocks()

