# Block encoding utility for CSAW 'the matrix' CTF
# Mapping: space=0, a=1, ..., z=26

def word_to_blocks(word, block_size=3, block_count=2):
    chars = [' '] + [chr(i) for i in range(ord('a'), ord('z')+1)]
    char_map = {c: i for i, c in enumerate(chars)}
    arr = [char_map[c] for c in word]
    # pad to length block_size*block_count with -1
    pad_len = block_size*block_count - len(arr)
    arr.extend([-1]*pad_len)
    return [arr[i*block_size:(i+1)*block_size] for i in range(block_count)]

def main():
    for word in ['matrix', 'enter']:
        blks = word_to_blocks(word)
        print(f"Word: {word}")
        print(f" Index list: {blks[0]+blks[1]}")
        print(f" Blocks:")
        for i,b in enumerate(blks):
            print(f"  Block {i+1}: {b}")

if __name__ == "__main__":
    main()

