import numpy as np
import itertools

# From encoder.py, the chars used for encoding
chars = list(" " + ''.join([chr(i) for i in range(ord('a'), ord('z')+1)]))
assert len(chars) == 27  # space + 26 lowercase

# Messages
messages = [
    [208, 255, 271, 108, 236, 171, 68, 219, 13],
    [177, 270, 173, 94, 79, 120, 65, 126, 30],
    [64, 159, 151, 108, 236, 171],
    [182, 233, 160, 35, 120, 2],
    [106, 226, 197, 106, 115, 124, 8, 39, -7],
]

# Partial info from encoder.py
ec_map = [3, 6, '?', '?', 4, 2, 1, 5, 7]
known_locs = [(0,0,3), (0,1,6), (1,1,4), (1,2,2), (2,0,1), (2,1,5), (2,2,7)]
# Let's brute-force the missing 2 values (ec_map[2], ec_map[3]) in range(0,27)
def matrix_variants():
    # Don't allow duplicate values
    s = set([3,6,4,2,1,5,7])
    for ec2 in range(0,27):
        if ec2 in s: continue
        for ec3 in range(0,27):
            if ec3 in s or ec3==ec2: continue
            arr = [3,6,ec2,ec3,4,2,1,5,7]
            # (size 3x3)
            yield np.array(arr).reshape((3,3))

def try_inverse(m):
    try:
        inv = np.linalg.inv(m)
        # If det is not integer, its probably inaccurate, skip those
        if not np.isclose(np.linalg.det(m), round(np.linalg.det(m))):
            return None
        return inv
    except np.linalg.LinAlgError:
        return None

def unpad_block(block):
    # Remove -1 padding (should only be at end)
    return [i for i in block if i != -1]

def decode_block(block, inv, force_int_round=True):
    # block: vector of 3 integers (ciphertext)
    # inv: inverse matrix
    # Returns: best-guess original 3-char block
    try:
        x = inv @ np.array(block).reshape((3,1))
        if force_int_round:
            x = np.round(x).astype(int)
        else:
            x = np.rint(x).astype(int)
        return unpad_block(list(x.flatten()))
    except Exception:
        return None

def indices_to_word(indices):
    # Convert list of ints to word using chars
    s = ''
    for idx in indices:
        if idx<0 or idx>=len(chars):
            s+='?'
        else:
            s+=chars[idx]
    return s

def plausible_word(word):
    # "plausible" if all are letters or space, and word contains at least some alphabet
    return any(c.isalpha() for c in word)

results = []

# For all possible key matrix guesses
for mat in matrix_variants():
    inv = try_inverse(mat)
    if inv is None:
        continue
    options = []
    for msg in messages:
        pts = []
        # Break in blocks of 3
        for i in range(0, len(msg), 3):
            block = msg[i:i+3]
            idxs = decode_block(block, inv)
            if idxs is not None and all(0<=v<len(chars) for v in idxs):
                pts.append(indices_to_word(idxs))
            else:
                pts.append('?')
        word = ''.join(pts)
        if plausible_word(word):
            options.append(word)
    if len(options)>0:
        results.append((mat,options))

# Gather per-message options
messages_best = [[] for _ in range(len(messages))]
for mat, words in results:
    for i,w in enumerate(words):
        if w not in messages_best[i]:
            messages_best[i].append(w)

for i,opts in enumerate(messages_best):
    print(f"Message {i+1} possible plaintexts:")
    for o in opts[:6]:
        print('  ',o)
    print()

