import ast
import subprocess

WORDS_FILE = 'ctf_wordlist.txt'
MESSAGES_FILE = 'messages.txt'
ENCODER_FILE = 'encoder.py'
TOP_N = 5

def read_words():
    with open(WORDS_FILE) as f:
        return [w.strip() for w in f if w.strip()]

def read_messages():
    lines = []
    with open(MESSAGES_FILE) as f:
        for i, l in enumerate(f):
            if i >= TOP_N:
                break
            lines.append(ast.literal_eval(l.strip()))
    return lines

def encode_word(word):
    # Accepts a word string, runs encoder.py with the word replaced in script body, grabs output list
    cmd = ['python3', ENCODER_FILE, word]
    p = subprocess.run(cmd, capture_output=True, text=True)
    output = p.stdout.strip()
    try:
        data = ast.literal_eval(output)
        if isinstance(data, list):
            return data
    except Exception:
        pass
    return None

def main():
    words = read_words()
    messages = read_messages()

    word_to_enc = {}
    enc_to_word = {}
    for word in words:
        enc = encode_word(word)
        if enc is not None:
            word_to_enc[word] = enc
            enc_to_word[tuple(enc)] = word

    results = []
    for idx, msg in enumerate(messages):
        w = enc_to_word.get(tuple(msg), None)
        if w is not None:
            results.append(f'Message {idx+1}: matches word "{w}".')
        else:
            results.append(f'Message {idx+1}: no match found from wordlist.')
    print('\n'.join(results))

if __name__ == '__main__':
    main()

