import z3
chars = list(" " + "abcdefghijklmnopqrstuvwxyz") # index = 0 (' '), ..., 26 ('z')
messages = [
    [208, 255, 271, 108, 236, 171, 68, 219, 13],
    [177, 270, 173, 94, 79, 120, 65, 126, 30],
    [64, 159, 151, 108, 236, 171],
    [182, 233, 160, 35, 120, 2],
    [106, 226, 197, 106, 115, 124, 8, 39, -7],
][:3]
solver = z3.Solver()
K = [[z3.Int(f'K_{i}_{j}') for j in range(3)] for i in range(3)]
for i in range(3):
    for j in range(3):
        solver.add(K[i][j] >= -32, K[i][j] <= 32)
plaintext_blocks = []
for idx, msg in enumerate(messages):
    nb = len(msg)//3
    ptblocks = []
    for b in range(nb):
        pt = [z3.Int(f'p_{idx}_{b}_{i}') for i in range(3)]
        ptblocks.append(pt)
        for x in pt:
            solver.add(z3.Or(z3.And(x >= 0, x <= 26), x == -1))
    plaintext_blocks.append(ptblocks)
for idx, msg in enumerate(messages):
    nb = len(msg)//3
    for b in range(nb):
        pt = plaintext_blocks[idx][b]
        ct = msg[b*3:(b+1)*3]
        for row in range(3):
            expr = sum(K[row][col]*pt[col] for col in range(3))
            solver.add(expr == ct[row])
if solver.check() == z3.sat:
    model = solver.model()
    K_val = [[model.evaluate(K[i][j]).as_long() for j in range(3)] for i in range(3)]
    print('Encoding Matrix:')
    for row in K_val:
        print(row)
    print('\nRecovered plaintexts:')
    for idx, ptblocks in enumerate(plaintext_blocks):
        pstr = ''
        for pt in ptblocks:
            charsblock = []
            for x in pt:
                val = model.evaluate(x).as_long()
                if val == -1:
                    charsblock.append('_')
                elif 0 <= val < len(chars):
                    charsblock.append(chars[val])
                else:
                    charsblock.append('?')
            pstr += ''.join(charsblock)
        print(f'Message {idx+1}:', pstr)
else:
    print('No solution found.')

